import csv
from collections import defaultdict


def load_rows(path):
    """Load rows from a CSV file into a list of dictionaries."""
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows


def sum_by_region(rows):
    """Calculate the total amount for each region."""
    total = defaultdict(float)
    for row in rows:
        region = row["region"].strip().title()
        amount = float(row["amount"])
        total[region] += amount
    return dict(total)


def top_regions(rows, n=3):
    """Return the top n regions by total amount."""
    total = sum_by_region(rows)
    ranked = sorted(total.items(), key=lambda kv: kv[1], reverse=True)
    return ranked[:n]


def monthly_totals(rows):
    """Calculate the total amount for each month."""
    total = defaultdict(float)
    for row in rows:
        month = row["date"][:7]
        total[month] += float(row["amount"])
    return dict(sorted(total.items()))


def report(path):
    """Generate a report of top regions and monthly totals."""
    rows = load_rows(path)
    top = top_regions(rows)
    for region, amount in top:
        print(f"{region:<12} {amount:>10.2f}")
    for month, amount in monthly_totals(rows).items():
        print(f"{month}  {amount:>10.2f}")


if __name__ == "__main__":
    report("sales.csv")
